import {parseSpotify} from './spotify-auth.js';
import {SpotifyUI} from './spotify-ui.js';
import {uid,putMedia,deleteMedia,releaseAsset} from './storage.js';
import {parseYouTube} from './markdown.js';
import {icon} from './icons.js';
import {fadeFields,readFades} from './fade-ui.js';
import {$,$$,esc,openForm,field,option,confirmAction,toast} from './ui.js';
import {formatTime} from './audio-engine.js';
import {YouTubeLibrary} from './youtube-library.js';
import {openMusicSettings} from './music-ui.js';
import {removeAudioAsset,removePlaylist} from './audio-assets.js';
import {filterAudioAssets} from './audio-search.js';

const labels={music:'Música',ambience:'Ambiência',sfx:'Efeito'};
const glyph=a=>a.provider==='youtube'?'youtube':({ambience:'rain',sfx:'bolt',music:'music'})[a.kind];
export class LibraryUI {
  constructor(ctx){this.ctx=ctx;this.filter='all';this.search='';this.playlistId=null;this.youtube=new YouTubeLibrary(ctx);this.spotify=new SpotifyUI(ctx);}
  render(root) {
    this.root=root;const state=this.ctx.state(),playlist=state.playlists.find(p=>p.id===this.playlistId);
    root.innerHTML=`<div class="library-heading"><div><div class="eyebrow">A ATMOSFERA TAMBÉM CONTA A HISTÓRIA</div><h1>Biblioteca de áudio <span class="count-badge">${state.audioAssets.length}</span></h1><p>Organize os sons que dão vida ao seu universo.</p></div><div class="heading-actions">${state.audioAssets.some(a=>a.builtin&&a.provider==='local')?`<button class="btn subtle" id="clearDemoAudio">${icon('trash')} Remover demos</button>`:''}<button class="btn outline" id="musicTransitionSettings">${icon('sliders')} Transições</button><button class="btn outline" id="openSpotify">♫ Spotify</button><button class="btn outline" id="addYoutube">${icon('youtube')} YouTube</button><button class="btn primary" id="uploadAudio">${icon('upload')} Enviar áudios</button></div></div><div class="library-layout"><aside class="playlist-sidebar"><span class="section-eyebrow">SUA BIBLIOTECA</span><button class="playlist-nav ${!playlist?'active':''}" data-library-all>${icon('headphones')} Todos os áudios <span>${state.audioAssets.length}</span></button><div class="section-heading"><span class="section-eyebrow">PLAYLISTS</span><button class="icon-btn" id="addPlaylist" aria-label="Criar playlist">${icon('plus')}</button></div>${state.playlists.map(p=>`<button class="playlist-nav ${p.id===this.playlistId?'active':''}" data-playlist="${esc(p.id)}">${icon(p.shuffle?'shuffle':'list')}<span>${esc(p.name)}</span><small>${p.assetIds.length}</small></button>`).join('')}<div class="library-info">${icon('shield')}<p>Arquivos e playlists são salvos neste navegador. Use o backup para levar a mesa a outro aparelho.</p></div></aside><section class="audio-browser"><div class="audio-browser-top"><div><h2>${esc(playlist?.name||'Todos os áudios')}</h2><span>${playlist?(playlist.shuffle?'Aleatório · uma rodada sem repetir faixas':'Ordem definida · reprodução contínua'):'Arquivos, ambientes e links do YouTube'}</span></div>${playlist?`<div class="heading-actions playlist-tools"><button class="btn outline small shuffle-toggle" id="shufflePlaylist" aria-pressed="${playlist.shuffle===true}" title="Alternar entre ordem definida e aleatória">${icon('shuffle')} Aleatório</button><button class="icon-btn" id="editPlaylist" title="Editar playlist" aria-label="Editar playlist">${icon('edit')}</button><button class="btn primary small" id="playPlaylist">${icon('play')} Reproduzir</button></div>`:''}</div><div class="library-filters"><div class="tab-pills" id="libraryFilters">${[['all','Todos'],['music','Músicas'],['ambience','Ambiências'],['sfx','Efeitos'],['youtube','YouTube'],['spotify','Spotify']].map(([v,l])=>`<button class="${this.filter===v?'active':''}" data-audio-filter="${v}">${l}</button>`).join('')}</div><label class="search-field">${icon('search')}<input type="search" id="audioSearch" placeholder="Buscar áudio ou tag…" aria-label="Buscar na biblioteca" value="${esc(this.search)}"></label></div><section id="youtubeInspector" class="youtube-inspector" hidden></section><div class="audio-table"><div class="audio-table-head"><span></span><span>TÍTULO / TAGS</span><span>TIPO</span><span>AÇÕES</span></div><div id="audioRows"></div></div><div class="library-footnote"><i></i> Seus áudios ficam neste navegador. Sons de demonstração também podem ser excluídos.</div></section></div>`;
    this.renderRows();this.youtube.mount(root);$('#clearDemoAudio',root)?.addEventListener('click',()=>this.clearDemos());$('#musicTransitionSettings',root).onclick=()=>openMusicSettings(this.ctx);
    $('#openSpotify',root).onclick=()=>this.spotify.open();$('#addYoutube',root).onclick=()=>this.addYouTube();$('#uploadAudio',root).onclick=()=>this.upload();$('#addPlaylist',root).onclick=()=>this.editPlaylist();
    $('[data-library-all]',root).onclick=()=>{this.playlistId=null;this.render(root);};
    $$('[data-playlist]',root).forEach(b=>b.onclick=()=>{this.playlistId=b.dataset.playlist;this.filter='all';this.render(root);});
    $$('[data-audio-filter]',root).forEach(b=>b.onclick=()=>{this.filter=b.dataset.audioFilter;$$('[data-audio-filter]',root).forEach(x=>x.classList.toggle('active',x===b));this.renderRows();});
    $('#audioSearch',root).oninput=e=>{this.search=e.target.value;this.renderRows();};
    $('#shufflePlaylist',root)?.addEventListener('click',()=>{playlist.shuffle=!playlist.shuffle;this.ctx.engine.refreshPlaylist(playlist);this.ctx.commit();toast(playlist.shuffle?'Modo aleatório ativado. Todas as faixas passam antes de repetir.':'Ordem definida ativada.');});
    $('#editPlaylist',root)?.addEventListener('click',()=>this.editPlaylist(playlist));$('#playPlaylist',root)?.addEventListener('click',()=>this.ctx.engine.playPlaylist(playlist).catch(e=>toast(e.message,true)));
  }
  renderRows() {
    if(!this.root?.isConnected)return;const state=this.ctx.state(),playlist=state.playlists.find(p=>p.id===this.playlistId),engine=this.ctx.engine;
    const source=playlist?playlist.assetIds.map(id=>state.audioAssets.find(a=>a.id===id)).filter(Boolean):state.audioAssets;
    const assets=source.filter(a=>(this.filter==='all'||this.filter==='youtube'&&a.provider==='youtube'||this.filter==='spotify'&&a.provider==='spotify'||this.filter===a.kind)&&(!this.search||`${a.name} ${a.tags||''}`.toLocaleLowerCase().includes(this.search.toLocaleLowerCase())));
    $('#audioRows',this.root).innerHTML=assets.length?assets.map(a=>{
      const active=engine.musicAsset?.id===a.id||engine.tracks.has('library:'+a.id);
      return `<div class="audio-row ${active?'playing':''}"><button class="asset-play ${a.provider==='youtube'?'youtube':''}" data-play-asset="${esc(a.id)}" aria-label="Reproduzir ${esc(a.name)}">${icon(active?'pause':glyph(a))}</button><div class="asset-title"><strong>${esc(a.name)} ${a.builtin?'<span class="demo-badge">DEMO</span>':''} ${a.boost>1?`<span class="boost-badge" title="Amplificação do arquivo">${Math.round(a.boost*100)}%</span>`:''}</strong><small>${esc(a.tags||'Sem tags')}<span> · ${a.provider==='youtube'?'YouTube'+(a.playlistId?' · Playlist':''):a.provider==='spotify'?'Spotify':a.provider==='upload'?'Arquivo enviado':'Áudio original'}${a.duration?' · '+formatTime(a.duration):''}</span></small></div><span class="kind-pill kind-${a.kind}">${labels[a.kind]}</span><div class="asset-actions">${a.provider==='spotify'?`<a class="spotify-source-link" href="${esc(parseSpotify(a.spotifyUri).url)}" target="_blank" rel="noopener" title="Abrir no Spotify"><img src="assets/spotify-icon.png" alt="Spotify"></a>`:''}${a.provider==='youtube'&&a.playlistId?`<button class="icon-btn" data-inspect-youtube="${esc(a.id)}" title="Ver faixas da playlist" aria-label="Ver faixas de ${esc(a.name)}">${icon('list')}</button>`:''}<button class="icon-btn" data-edit-asset="${esc(a.id)}" title="Editar áudio" aria-label="Editar ${esc(a.name)}">${icon('edit')}</button><button class="icon-btn delete-audio" data-delete-asset="${esc(a.id)}" title="Excluir da biblioteca" aria-label="Excluir da biblioteca: ${esc(a.name)}">${icon('trash')}</button></div></div>`;
    }).join(''):`<div class="empty-state">${icon('headphones')}<h3>Nenhum áudio por aqui</h3><p>${this.search?'Tente outro nome ou tag.':playlist?'Adicione faixas usando o botão de editar playlist.':'Envie um arquivo ou adicione um link do YouTube.'}</p></div>`;
    $$('[data-play-asset]',this.root).forEach(b=>b.onclick=async()=>{const asset=state.audioAssets.find(a=>a.id===b.dataset.playAsset);try{
      if(asset.provider==='youtube'||asset.kind==='music'){if(engine.musicAsset?.id===asset.id)engine.toggleTransport();else if(playlist)await engine.playPlaylist(playlist,source.findIndex(a=>a.id===asset.id));else await engine.playMusic(asset);}
      else if(asset.kind==='ambience')await engine.toggleLibraryLayer(asset);else await engine.oneShot(asset);
      this.renderRows();
    }catch(error){toast(error.message,true);}});
    $$('[data-inspect-youtube]',this.root).forEach(b=>b.onclick=()=>this.youtube.open(state.audioAssets.find(a=>a.id===b.dataset.inspectYoutube)));
    $$('[data-delete-asset]',this.root).forEach(b=>b.onclick=()=>this.deleteAsset(state.audioAssets.find(a=>a.id===b.dataset.deleteAsset)));
    $$('[data-edit-asset]',this.root).forEach(b=>b.onclick=()=>this.editAsset(state.audioAssets.find(a=>a.id===b.dataset.editAsset)));
  }
  upload() {
    openForm({title:'Enviar áudios',submit:'Adicionar à biblioteca',body:'<p class="dialog-description">Músicas, ambiências ou efeitos da sua mesa. Você pode selecionar vários arquivos.</p><label class="file-drop"><span>♫</span><strong>Escolher arquivos de áudio</strong><small>MP3, WAV, OGG, M4A, FLAC ou WebM · até 100 MB por arquivo</small><input type="file" name="audioFiles" accept="audio/*,.mp3,.wav,.ogg,.m4a,.flac,.webm,.aac,.opus" multiple required></label><div class="form-grid"><label class="field"><span>Tipo</span><select name="kind">'+Object.entries(labels).map(([v,l])=>option(v,l,v==='music')).join('')+'</select></label>'+field('Tags (opcional)','tags','','placeholder="Suspense, combate, chuva…" maxlength="200"')+'</div>',onSubmit:async form=>{
      const files=form.getAll('audioFiles').filter(f=>f.size);if(!files.length)throw new Error('Selecione um arquivo de áudio.');
      if(files.some(f=>f.size>100*1024*1024))throw new Error('Cada arquivo deve ter até 100 MB.');
      if(files.some(f=>!f.type.startsWith('audio/')&&!/\.(mp3|wav|ogg|m4a|flac|webm|aac|opus)$/i.test(f.name)))throw new Error('Selecione somente arquivos de áudio.');
      const assets=[];try{for(const file of files){const id=uid('asset');await putMedia(id,file);assets.push({id,name:file.name.replace(/\.[^.]+$/,''),filename:file.name,kind:form.get('kind'),tags:String(form.get('tags')).trim(),provider:'upload',size:file.size});}}catch(error){if(assets.length){this.ctx.state().audioAssets.push(...assets);this.ctx.commit();}throw error;}
      this.ctx.state().audioAssets.push(...assets);this.ctx.commit();toast(`${assets.length} áudio${assets.length>1?'s':''} adicionado${assets.length>1?'s':''}.`);return ()=>this.render(this.root);
    }});
  }
  addYouTube() {
    openForm({title:'Adicionar do YouTube',submit:'Adicionar à biblioteca',body:'<p class="dialog-description">Cole um link de vídeo ou playlist. O player oficial permanece visível e continua ativo durante a navegação.</p>'+field('Link do YouTube','url','','type="url" required placeholder="https://www.youtube.com/watch?v=…"')+field('Nome na biblioteca','name','','required maxlength="120" placeholder="Trilha de investigação"')+'<div class="form-grid">'+field('Iniciar em (segundos)','start','','type="number" min="0" step="1" placeholder="Usar o tempo do link"')+field('Tags (opcional)','tags','','maxlength="200" placeholder="Investigação, tensão…"')+'</div><p class="form-hint">Vídeos privados ou com incorporação bloqueada podem não tocar. No celular, o primeiro play pode exigir um toque no vídeo.</p>',onSubmit:form=>{
      const parsed=parseYouTube(String(form.get('url')));const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');
      const asset={id:uid('asset'),name,provider:'youtube',kind:'music',shuffle:!!parsed.playlistId,tags:String(form.get('tags')).trim(),url:String(form.get('url')),...parsed,start:form.get('start')===''?parsed.start:Number(form.get('start'))};
      this.ctx.state().audioAssets.push(asset);this.ctx.commit();toast('Link adicionado à biblioteca.');return ()=>this.render(this.root);
    }});
  }
  deleteAsset(asset){
    if(!asset)return;
    confirmAction('Excluir áudio?',`“${asset.name}” será excluído da biblioteca, das playlists e das configurações sonoras que o utilizam. O texto das cenas será mantido.`,async()=>{
      if(asset.provider==='upload')await deleteMedia(asset.id);
      await this.ctx.engine.removeAsset(asset.id);removeAudioAsset(this.ctx.state(),asset.id);releaseAsset(asset.id);
      const playlist=this.ctx.state().playlists.find(p=>p.id===this.ctx.engine.playlist?.id);if(playlist)this.ctx.engine.refreshPlaylist(playlist);
      this.ctx.commit();toast('Áudio excluído da biblioteca.');return ()=>this.render(this.root);
    });
  }
  clearDemos(){
    const assets=this.ctx.state().audioAssets.filter(a=>a.builtin&&a.provider==='local');if(!assets.length)return;
    confirmAction('Remover sons de demonstração?',`Os ${assets.length} sons de demonstração serão retirados da biblioteca e das configurações que os utilizam. Seus áudios enviados e os textos das cenas serão mantidos.`,async()=>{
      for(const asset of assets){await this.ctx.engine.removeAsset(asset.id);removeAudioAsset(this.ctx.state(),asset.id);releaseAsset(asset.id);}
      const state=this.ctx.state(),demo=state.playlists.find(p=>p.id==='playlist-sao-martinho');if(demo&&!demo.assetIds.length){removePlaylist(state,demo.id);this.ctx.engine.ambiences.removePlaylist(demo.id);if(this.playlistId===demo.id)this.playlistId=null;}
      const active=state.playlists.find(p=>p.id===this.ctx.engine.playlist?.id);if(active)this.ctx.engine.refreshPlaylist(active);this.ctx.commit();toast('Demonstrações removidas. Seus arquivos foram mantidos.');
    },'Remover demonstrações');
  }
  editAsset(asset) {
    if(asset.provider==='spotify'){
      openForm({title:'Editar item Spotify',body:field('Nome na biblioteca','name',asset.name,'required maxlength="120"')+field('Tags','tags',asset.tags||'','maxlength="200"')+(asset.spotifyUri.startsWith('spotify:playlist:')?`<label class="check-field"><input type="checkbox" name="shuffle" ${asset.shuffle?'checked':''}><span>Reproduzir playlist em ordem aleatória</span></label>`:'')+`<p class="form-hint">Spotify usa reprodução oficial, sem amplificação e sem fades nesta versão.</p><button type="button" class="btn danger" id="deleteSpotifyAsset">Excluir da biblioteca</button>`,onReady:root=>{$('#deleteSpotifyAsset',root).onclick=()=>this.deleteAsset(asset);},onSubmit:form=>{const name=String(form.get('name')).trim();if(!name)throw Error('Informe um nome.');asset.name=name;asset.tags=String(form.get('tags')).trim();if(asset.spotifyUri.startsWith('spotify:playlist:'))asset.shuffle=form.has('shuffle');this.ctx.commit();}});return;
    }
    openForm({title:'Editar áudio',body:field('Nome','name',asset.name,'required maxlength="120"')+'<div class="form-grid"><label class="field"><span>Tipo</span><select name="kind" '+(asset.provider==='youtube'?'disabled':'')+'>'+Object.entries(labels).map(([v,l])=>option(v,l,v===asset.kind)).join('')+'</select></label>'+field('Tags','tags',asset.tags||'','maxlength="200"')+'</div>'+(asset.provider==='youtube'?field('URL do YouTube','url',asset.url,'type="url" required')+field('Início (segundos)','start',asset.start||0,'type="number" min="0"')+(asset.playlistId?`<label class="check-field"><input type="checkbox" name="shuffle" ${asset.shuffle?'checked':''}><span>Reproduzir esta playlist em ordem aleatória</span></label>`:''):'')+(asset.provider!=='youtube'?`<section class="asset-amplification"><label class="field"><span>Amplificação do arquivo <output id="boostValue">${Math.round((asset.boost??1)*100)}%</output></span><input type="range" name="boost" id="assetBoost" min="100" max="400" step="5" value="${Math.round((asset.boost??1)*100)}" aria-label="Amplificação do arquivo de 100 a 400 por cento"></label><p class="form-hint">Compense gravações baixas sem editar o arquivo. 100% mantém o nível original; valores altos podem distorcer. O ajuste é aplicado ao salvar.</p></section>`:'<p class="form-hint">O player do YouTube controla o volume até 100%. A amplificação adicional está disponível para arquivos enviados.</p>')+(asset.provider!=='youtube'?fadeFields(asset,'Padrão para efeitos e loops deste arquivo. Efeitos saem em fade antes de terminar; loops ao desligar. Vazio usa o comportamento padrão; 0 desativa o fade. Os novos tempos valem no próximo play.'):'' )+`<p class="form-hint">Mudanças de nome e tags não interrompem a reprodução.</p><button type="button" class="btn danger full" id="deleteAsset">Excluir da biblioteca</button>`,onReady:root=>{$('#deleteAsset',root)?.addEventListener('click',()=>this.deleteAsset(asset));$('#assetBoost',root)?.addEventListener('input',e=>$('#boostValue',root).textContent=e.target.value+'%');},onSubmit:form=>{
      const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');
      if(asset.provider==='youtube'){Object.assign(asset,parseYouTube(String(form.get('url'))));asset.url=String(form.get('url'));asset.start=Number(form.get('start'));if(asset.playlistId)this.ctx.engine.setYouTubeShuffle(asset,form.has('shuffle'));}
      if(asset.provider!=='youtube'){this.ctx.engine.setAssetBoost(asset.id,Number(form.get('boost'))/100);Object.assign(asset,readFades(form));}asset.name=name;asset.tags=String(form.get('tags')).trim();asset.kind=asset.provider==='youtube'?'music':form.get('kind');this.ctx.commit();return ()=>this.render(this.root);
    }});
  }
  editPlaylist(playlist=null){
    let ids=[...new Set(playlist?.assetIds||[])],query='',filter='all',limit=100;const state=this.ctx.state();
    const matches=()=>filterAudioAssets(state.audioAssets,query,filter);
    const renderSelected=root=>{
      $('#playlistSelectedCount',root).textContent=ids.length+' faixas selecionadas';
      $('#playlistTracks',root).innerHTML=ids.map((id,i)=>{const asset=state.audioAssets.find(a=>a.id===id);if(!asset)return '';return `<div class="playlist-edit-row"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(asset.name)}</strong><button type="button" class="icon-btn" data-track-up="${i}" aria-label="Mover ${esc(asset.name)} para cima">↑</button><button type="button" class="icon-btn" data-track-down="${i}" aria-label="Mover ${esc(asset.name)} para baixo">↓</button><button type="button" class="icon-btn" data-track-remove="${i}" aria-label="Retirar ${esc(asset.name)} da playlist">${icon('close')}</button></div>`;}).join('')||'<p class="empty-small">Marque as faixas na biblioteca abaixo.</p>';
      $$('[data-track-up]',root).forEach(b=>b.onclick=()=>{const i=+b.dataset.trackUp;if(i>0)[ids[i-1],ids[i]]=[ids[i],ids[i-1]];renderSelected(root);});
      $$('[data-track-down]',root).forEach(b=>b.onclick=()=>{const i=+b.dataset.trackDown;if(i<ids.length-1)[ids[i+1],ids[i]]=[ids[i],ids[i+1]];renderSelected(root);});
      $$('[data-track-remove]',root).forEach(b=>b.onclick=()=>{ids.splice(+b.dataset.trackRemove,1);renderSelected(root);renderChoices(root);});
    };
    const renderChoices=root=>{
      const assets=matches(),remaining=assets.filter(a=>!ids.includes(a.id));$('#playlistSearchCount',root).textContent=assets.length+' resultados';
      $('#playlistAddMatches',root).disabled=!remaining.length;$('#playlistAddMatches',root).textContent=remaining.length?'Adicionar encontrados ('+remaining.length+')':'Todos os resultados selecionados';
      $('#playlistChoices',root).innerHTML=assets.slice(0,limit).map(asset=>`<label class="audio-choice ${ids.includes(asset.id)?'selected':''}"><input type="checkbox" data-playlist-choice="${esc(asset.id)}" ${ids.includes(asset.id)?'checked':''}><span class="audio-choice-art">${icon(glyph(asset))}</span><span><strong>${esc(asset.name)}</strong><small>${esc([labels[asset.kind],asset.provider==='youtube'?'YouTube'+(asset.playlistId?' · Playlist':''):'Arquivo',asset.tags].filter(Boolean).join(' · '))}</small></span></label>`).join('')||'<p class="empty-small">Nenhum áudio encontrado. Tente outro nome ou tag.</p>';
      $('#playlistMoreChoices',root).hidden=assets.length<=limit;
      $$('[data-playlist-choice]',root).forEach(input=>input.onchange=()=>{const id=input.dataset.playlistChoice;if(input.checked&&!ids.includes(id))ids.push(id);if(!input.checked)ids=ids.filter(value=>value!==id);input.closest('.audio-choice').classList.toggle('selected',input.checked);renderSelected(root);const remaining=matches().filter(a=>!ids.includes(a.id));$('#playlistAddMatches',root).disabled=!remaining.length;$('#playlistAddMatches',root).textContent=remaining.length?'Adicionar encontrados ('+remaining.length+')':'Todos os resultados selecionados';});
    };
    openForm({title:playlist?'Editar playlist':'Criar playlist',wide:true,body:field('Nome da playlist','name',playlist?.name||'','required maxlength="100"')+`<label class="check-field"><input type="checkbox" name="shuffle" ${(playlist?playlist.shuffle===true:true)?'checked':''}><span>Reproduzir em ordem aleatória, sem repetir até completar a lista</span></label><div class="playlist-selection-heading"><span class="section-eyebrow">SUA SELEÇÃO / ORDEM</span><small id="playlistSelectedCount"></small></div><div id="playlistTracks" class="playlist-selected-tracks"></div><section class="playlist-audio-picker"><header><h3>Adicionar áudios à playlist</h3><span id="playlistSearchCount"></span></header><label class="search-field">${icon('search')}<input type="search" id="playlistAudioSearch" placeholder="Buscar por nome, arquivo ou tag…" aria-label="Buscar áudios para esta playlist" autocomplete="off"></label><div class="tab-pills">${[['all','Todos'],['music','Músicas'],['ambience','Ambiências'],['sfx','Efeitos'],['youtube','YouTube'],['spotify','Spotify']].map(([v,l])=>`<button type="button" data-playlist-filter="${v}" class="${v==='all'?'active':''}">${l}</button>`).join('')}</div><div id="playlistChoices" class="playlist-audio-choices"></div><button type="button" class="btn subtle full" id="playlistMoreChoices">Mostrar mais resultados</button><button type="button" class="btn outline full" id="playlistAddMatches">Adicionar encontrados</button></section><p class="form-hint">Marque várias faixas de uma vez. Use as setas para organizar a sequência quando o aleatório estiver desligado. Retirar uma faixa daqui mantém o arquivo na biblioteca.</p>${playlist?'<button type="button" class="btn danger full" id="deletePlaylist">Excluir playlist</button>':''}`,onReady:root=>{
      renderSelected(root);renderChoices(root);$('#playlistAudioSearch',root).oninput=e=>{query=e.target.value;limit=100;renderChoices(root);};$('#playlistAudioSearch',root).onkeydown=e=>{if(e.key==='Enter')e.preventDefault();};
      $$('[data-playlist-filter]',root).forEach(button=>button.onclick=()=>{filter=button.dataset.playlistFilter;limit=100;$$('[data-playlist-filter]',root).forEach(b=>b.classList.toggle('active',b===button));renderChoices(root);});
      $('#playlistMoreChoices',root).onclick=()=>{limit+=100;renderChoices(root);};$('#playlistAddMatches',root).onclick=()=>{ids=[...new Set([...ids,...matches().map(a=>a.id)])];renderSelected(root);renderChoices(root);};
      $('#deletePlaylist',root)?.addEventListener('click',()=>confirmAction('Excluir playlist?',`A playlist “${playlist.name}” será excluída. Os áudios continuam na biblioteca; os vínculos em ambientes, cenas e cues serão removidos.`,()=>{removePlaylist(state,playlist.id);this.ctx.engine.ambiences.removePlaylist(playlist.id);if(this.ctx.engine.playlist?.id===playlist.id){this.ctx.engine.playlist=null;this.ctx.engine.musicOrder=null;this.ctx.engine.clearPreload();}this.playlistId=null;this.ctx.commit();return ()=>this.render(this.root);}));
    },onSubmit:form=>{
      const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');if(playlist){playlist.name=name;playlist.assetIds=ids;playlist.shuffle=form.has('shuffle');this.ctx.engine.refreshPlaylist(playlist);}else{const p={id:uid('playlist'),name,assetIds:ids,shuffle:form.has('shuffle')};state.playlists.push(p);this.playlistId=p.id;}this.ctx.commit();return ()=>this.render(this.root);
    }});
  }
}
